import sympy as S
from fractions import Fraction as F
from .authoring import maker,finish
from .common import section
q=maker('log-trig-synthesis',['change of base','domain filtering','trigonometric identities'])
x=S.Symbol('x',positive=True)
p=[
q(1,r'For x>0, x≠1, $\log_2x+\log_x2=5/2$. Find the sum of all possible x.',4+S.sqrt(2),[(F(5,2),'Report the sum of the transformed logarithms.'),(6,'Treat a logarithm value one-half as x=2.'),(4-S.sqrt(2),'Lose the positive exponential root.'),(S.sqrt(2),'Discard one valid logarithm value.')],[r'Let t=log₂x. Change of base gives log_x2=1/t, with t≠0.',r'The equation 2t²-5t+2=0 gives t=2 or 1/2.',r'Thus x=4 or √2, both satisfying the original domain; their sum is 4+√2.'],['Express both logarithms using the same base.' ,'Solve for the logarithm first, then recover x.'],'Turn reciprocal logarithms into a quadratic with domain checks.',lambda:sum(2**t for t in S.solve(2*S.Symbol('t')**2-5*S.Symbol('t')+2,S.Symbol('t'))),'Exact transformed roots and substitution into both logarithms.'),
q(2,r'Find the real solution of $\log_2(x-1)+\log_2(x-3)=3$.',5,[(4,'Use the sum of the two arguments instead of their product.'),(-1,'Keep the quadratic root outside the logarithm domain.'),(8,'Report the exponential target instead of x.'),(3,'Include a zero logarithm argument.')],[r'The original domain is x>3.',r'Combine the logarithms to get (x-1)(x-3)=8, or x²-4x-5=0.',r'The candidates are 5 and -1; only 5 is in the domain.'],['Require both logarithm arguments to be positive before combining.' ,'Filter the quadratic roots using the original domain.'],'Preserve logarithm domains through a product transformation.',lambda:next(r for r in S.solve((x-1)*(x-3)-8,x) if r>3),'Exact roots filtered by the original arguments.',2),
q(3,r'For x>0, $\log_3x+\log_9x+\log_{27}x=11$. Find x.',729,[(6,'Report log₃x instead of x.'),(243,'Use an incorrect sum of base-change coefficients.'),(177147,'Ignore the different bases.'),(81,'Average the logarithms without changing base.')],[r'Let t=log₃x. The three terms become t,t/2,t/3.',r'The coefficient sum is 11/6, so (11/6)t=11 and t=6.',r'Thus x=3⁶=729.'],['The three bases are powers of one common base.' ,'Change each logarithm before adding.'],'Reduce multiple logarithm bases to one linear variable.',lambda:3**S.solve(S.Eq(S.Symbol('t')+S.Symbol('t')/2+S.Symbol('t')/3,11),S.Symbol('t'))[0],'Exact common-base equation.',2),
q(4,r'For x>0, $\log_2x\,\log_4x\,\log_8x=36$. Find x.',64,[(6,'Report the transformed logarithm.'),(8,'Treat the product of bases as the base of one logarithm.'),(216,'Report the cube of the transformed variable.'),(32,'Use an exponent one below the solution.')],[r'With t=log₂x, the product is t·(t/2)·(t/3)=t³/6.',r'Thus t³=216 and the unique real t is six.',r'Therefore x=2⁶=64.'],['Convert all three factors to the same logarithm.' ,'A product of logarithms is not a logarithm of a product.'],'Use common-base substitution in a nonlinear logarithm equation.',lambda:2**S.real_root(36*6,3),'Exact real cubic root followed by inverse transformation.'),
q(5,r'Find x if $\log_2(\log_3x)=2$.',81,[(9,'Apply only the outer inverse and use the wrong exponent.'),(4,'Report the inner logarithm.'),(6,'Multiply bases instead of undoing nested functions.'),(27,'Use exponent three rather than four.')],[r'The outer logarithm requires log₃x>0, hence x>1.',r'Undo the outer logarithm first: log₃x=2²=4.',r'Undo the inner logarithm: x=3⁴=81, which satisfies the domain.'],['Undo nested functions from the outside inward.' ,'Check the inner logarithm is a positive argument for the outer one.'],'Invert a nested function in the correct order.',lambda:3**(2**2),'Direct substitution gives log₂4=2.',2),
q(6,r'Find the sum of all real solutions of $4^x-5\cdot2^x+4=0$.',2,[(5,'Report the sum of the positive exponential substitutions.'),(4,'Report only the larger substitution root.'),(1,'Omit the zero exponent solution.'),(3,'Treat the substitution roots as linear shifts of x.')],[r'Let u=2^x, which is strictly positive. Then u²-5u+4=0.',r'The roots u=1 and u=4 are both admissible.',r'They give x=0 and x=2, whose sum is two.'],['Recognize 4^x as the square of 2^x.' ,'Recover exponents after solving the polynomial.'],'Polynomialize an exponential equation with a positive substitution.',lambda:sum(S.log(u,2) for u in S.solve(x*x-5*x+4,x)),'Exact polynomial roots and inverse exponential map.'),
q(7,r'How many integers x satisfy $\log_{1/2}(x-1)>-2$?',3,[(4,'Include the equality endpoint x=5.'),(5,'Include an undefined argument at x=1.'),(2,'Exclude a valid interior integer.'),(0,'Reverse the inequality in the wrong direction and assume no bounded solutions.')],[r'The domain is x>1.',r'A logarithm with base between zero and one is decreasing, so the inequality becomes x-1<(1/2)^(-2)=4.',r'Thus 1<x<5, giving x=2,3,4: three integers.'],['Check whether the logarithm is increasing or decreasing.' ,'Preserve the original positive-argument condition.'],'Reverse an inequality through a decreasing logarithm.',lambda:sum(1<n<5 for n in range(-10,11)),'Exact interval from the monotonic inverse.'),
q(8,r'For $0<\theta<\pi/2$, $\sin\theta+\cos\theta=\sqrt{3/2}$. Find $\tan\theta+\cot\theta$.',4,[(2,'Omit the factor two in the squared sum.'),(F(1,4),'Report sinθ cosθ instead of its reciprocal.'),(F(3,2),'Report the squared given value.'),(3,'Add tangent and cotangent as if their denominators were equal.')],[r'Square the given equation: 1+2sinθ cosθ=3/2, so sinθ cosθ=1/4.',r'Combining the target fractions gives (sin²θ+cos²θ)/(sinθ cosθ).',r'The numerator is one and the denominator is nonzero in the stated interval, so the answer is four.'],['Square the given sum to recover a product.' ,'Combine tangent and cotangent over a common denominator.'],'Connect a symmetric trigonometric sum to a rational target.',lambda:S.simplify(S.tan(S.pi/12)+1/S.tan(S.pi/12)),'Independent admissible angle θ=π/12; symmetry gives the other solution.'),
q(9,r'If tanθ=2, find cos(2θ).',F(-3,5),[(F(3,5),'Reverse the numerator difference.'),(F(4,5),'Compute sin²θ instead.'),(F(1,5),'Compute cos²θ instead.'),(-3,'Omit the normalization by one plus tangent squared.')],[r'Divide cos²θ-sin²θ by cos²θ+sin²θ.',r'This gives cos(2θ)=(1-tan²θ)/(1+tan²θ).',r'Substituting two gives (1-4)/(1+4)=-3/5, independent of the quadrant ambiguity in θ.'],['Express the double angle as a ratio normalized by sin²+cos².' ,'Divide numerator and denominator by cos²θ.'],'Choose an identity that uses the supplied ratio directly.',lambda:S.simplify(S.cos(2*S.atan(2))),'Independent exact angle substitution.',2),
q(10,r'How many solutions in $0\le\theta<2\pi$ satisfy $\sin(2\theta)=\cos\theta$?',4,[(2,'Divide by cosθ and lose its zero solutions.'),(3,'Miss one quadrant for sinθ=1/2.'),(5,'Count 2π as a new endpoint.'),(6,'Double-count overlapping branches.')],[r'Use sin(2θ)=2sinθ cosθ and factor to get cosθ(2sinθ-1)=0.',r'The first factor gives θ=π/2,3π/2; the second gives θ=π/6,5π/6.',r'The branches do not overlap, so there are four solutions in the half-open interval.'],['Factor before dividing by a trigonometric expression.' ,'Solve each zero-factor branch on the specified interval.'],'Preserve solutions when a potential divisor can vanish.',lambda:len({S.pi/2,3*S.pi/2,S.pi/6,5*S.pi/6}),'All four angles substituted exactly; unit-circle branches exhaust the factored equation.'),
q(11,r'A triangle has two sides 7 and 8 with included angle 60°. Find its circumradius.',S.sqrt(19),[(S.sqrt(57),'Report the opposite side.'),(S.sqrt(19)/2,'Lose a factor two in the extended sine rule.'),(7,'Use one given side as a radius.'),(S.sqrt(76),'Double the circumradius.')],[r'The opposite side c satisfies c²=7²+8²-2·7·8·cos60°=57.',r'The extended sine rule gives 2R=c/sin60°.',r'Thus R=√57/√3=√19.'],['Use the cosine rule to recover the side opposite the known angle.' ,'Then connect that side to the circumradius through the sine rule.'],'Chain the cosine and extended sine rules.',lambda:S.Circle(S.Point(0,0),S.Point(8,0),S.Point(S.Rational(7,2),7*S.sqrt(3)/2)).radius,'Independent coordinate circumcircle.'),
q(12,r'Triangle ABC has A=30°, B=45°, and side a=6 opposite A. Find side c opposite C.',3*(S.sqrt(6)+S.sqrt(2)),[(6*S.sqrt(2),'Report side b.'),(3*(S.sqrt(6)-S.sqrt(2)),'Use sin15° instead of sin105°.'),(6*(S.sqrt(6)+S.sqrt(2)),'Omit the denominator four in the angle-sum expansion.'),(12,'Replace sin105° by one.')],[r'The third angle is 105°, so the sine rule gives c=6sin105°/sin30°=12sin105°.',r'Use sin(60°+45°)=√6/4+√2/4.',r'Therefore c=3(√6+√2).'],['Find the third angle before choosing a trigonometric identity.' ,'Expand 105° as a sum of special angles.'],'Combine triangle constraints with an angle-addition identity.',lambda:S.simplify(12*S.sin(7*S.pi/12)),'Independent exact trigonometric evaluation.'),
q(13,r'For $0<\theta<\pi$, cosθ=1/3. Find sin(3θ)/sinθ.',F(-5,9),[(F(5,9),'Lose the subtraction in the triple-angle identity.'),(F(1,3),'Assume the ratio equals cosθ.'),(F(8,9),'Report sin²θ.'),(3,'Assume sin(3θ)=3sinθ without the cubic correction.')],[r'The interval ensures sinθ≠0. The triple-angle identity gives sin(3θ)/sinθ=3-4sin²θ.',r'Since cos²θ=1/9, sin²θ=8/9.',r'The ratio is 3-32/9=-5/9.'],['Use an angle-multiple identity before solving for θ.' ,'Divide only after checking the denominator is nonzero.'],'Reduce a multiple-angle ratio to a known squared function.',lambda:S.simplify(S.expand_trig(S.sin(3*S.acos(S.Rational(1,3))))/S.sin(S.acos(S.Rational(1,3)))),'Independent exact angle substitution.'),
q(14,r'What is the greatest possible value of $3\sin\theta+4\cos\theta$ over real θ?',5,[(7,'Maximize sine and cosine independently at incompatible angles.'),(25,'Report the squared bound.'),(4,'Use only the larger coefficient.'),(S.sqrt(7),'Take the square root of the coefficient sum.')],[r'Cauchy–Schwarz gives (3sinθ+4cosθ)²≤(3²+4²)(sin²θ+cos²θ)=25.',r'The positive upper bound is five.',r'It is attained when sinθ=3/5 and cosθ=4/5, which is a point on the unit circle.'],['Treat sine and cosine as coordinates of a unit vector.' ,'Check whether the coefficient direction gives a feasible equality point.'],'Optimize a trigonometric linear combination with an attainable vector bound.',lambda:3*S.Rational(3,5)+4*S.Rational(4,5),'Unit-circle equality witness and independent amplitude √(3²+4²).',2)]
e=[
q(101,r'Find the sum of the real solutions of $\log_3x+\log_x3=10/3$.',27+3**S.Rational(1,3),[(F(10,3),'Report the logarithm-variable sum.'),(30,'Treat a one-third logarithm as x=3.'),(27-3**S.Rational(1,3),'Negate the second positive solution.'),(3**S.Rational(1,3),'Discard the larger admissible solution.')],[r'The domain is x>0 and x≠1. Set t=log₃x; then t≠0 and change of base makes the other logarithm 1/t.',r'The equation becomes 3t²-10t+3=0, whose roots are 3 and 1/3.',r'Undo the substitution to obtain x=27 and the positive cube root of three. Their sum is the answer.',r'The transformed roots are not the requested x-values. Both original bases and arguments satisfy the domain, so neither candidate is extraneous.'],['Use one logarithm variable and its reciprocal.' ,'Undo the substitution only after solving the quadratic.'],'Explain a reciprocal-logarithm transformation and its domain.',lambda:sum(3**t for t in S.solve(3*S.Symbol('t')**2-10*S.Symbol('t')+3,S.Symbol('t'))),'Exact transformed roots and domain verification.'),
q(102,r'If sinθ+cosθ=6/5, find sinθ cosθ.',F(11,50),[(F(18,25),'Halve the square without removing sin²+cos².'),(F(6,25),'Square the sum incorrectly.'),(F(11,25),'Forget the cross-term coefficient two.'),(F(1,5),'Subtract one before squaring.')],[r'Square both sides to get sin²θ+cos²θ+2sinθ cosθ=36/25.',r'The first two terms sum to one, leaving 2sinθ cosθ=11/25.',r'The product is 11/50. The original value 6/5 lies within the possible sum range [-√2,√2].',r'For a later target such as tanθ+cotθ, this product would be more useful than finding either trigonometric function separately.'],['Square the sum and keep the cross term.' ,'Use the Pythagorean identity before isolating the product.'],'Choose a symmetric quantity suited to the target.',lambda:(S.Rational(6,5)**2-1)/2,'Independent algebraic identity and feasibility check.',2)]
finish('log-trig-synthesis','AMC 12: logarithmic & trigonometric transformations','AMC 12 extensions','logarithms trigonometry trig-geometry inequalities-domains',41,'609–652',
 [r'Logarithm and trigonometric equations often become familiar algebra after a carefully chosen substitution. The challenge is to preserve the function’s domain, its monotonicity, and any solutions that could be lost by division.',r'This AMC 12 study connects change of base, exponential substitutions, symmetric trigonometric expressions, and triangle geometry. The target is usually a transformed quantity, so recovering an angle or every individual function value may be unnecessary.'],
 [section('Use one logarithm variable',r'Logarithms with related bases should first be expressed in a common base. If t=log_b x, then log_(b^m)x=t/m and log_x b=1/t. The reciprocal relation requires x≠1 as well as positive valid bases and arguments.',r'Combining logarithms into a product can create a polynomial equation, but its roots must satisfy each original argument restriction. The product of two negative arguments may be positive even though neither original logarithm exists. Write the individual positivity conditions before combining.',r'An exponential polynomial such as b^(2x)+Ab^x+B can be transformed with u=b^x, but u is strictly positive. After solving the polynomial, discard nonpositive candidates and invert the exponential for each remaining one. In nested logarithms, undo functions from the outside inward and check every inner argument.'),
 section('Preserve monotonicity and zero branches',r'A logarithm with base greater than one is increasing; with base between zero and one it is decreasing. An inequality changes direction when passed through a decreasing function. Keep the positive-argument domain alongside the resulting interval, especially at strict endpoints.',r'Trigonometric identities should be chosen to match the supplied information. Squaring sinθ+cosθ recovers sinθ cosθ. Combining tanθ and cotθ over a common denominator then uses that product directly. This avoids solving for θ and introduces only the denominator conditions that the original target already requires.',r'Factor a trigonometric equation before dividing. Dividing sin(2θ)=cosθ by cosθ discards the entire cosθ=0 branch. After factoring, solve every branch on the stated interval, remove duplicate angles, and respect a half-open endpoint such as [0,2π).'),
 section('Connect identities to geometry and bounds',r'The cosine rule converts two sides and an included angle into the opposite side. The extended sine rule then connects that side to the circumradius. These are useful in sequence: the first recovers the missing chord, and the second uses the chord’s subtended angle.',r'Angle-addition formulas can produce exact values for angles such as 105° from familiar angles. A multiple-angle ratio may simplify using a squared sine or cosine without needing the sign of the other function, but the denominator must still be nonzero.',r'A linear combination a sinθ+b cosθ is a dot product between a coefficient vector and a unit vector. Cauchy–Schwarz gives the amplitude √(a²+b²), and the coefficient direction supplies an equality point. Maximizing sine and cosine independently would demand incompatible angles; the unit-circle constraint is what makes the bound correct.')],
 ['Use common-base and exponential substitutions with full domains.','Preserve monotonicity, zero-factor branches, and interval endpoints.','Combine trigonometric identities with geometric or inequality constraints.'],
 [r'Derive reciprocal and power-base logarithm relations from change of base.',r'Expand a squared sine-cosine sum and apply sin²+cos²=1.',r'Interpret a sinθ+b cosθ as a dot product and verify the amplitude equality point.'],
 'Algebraic candidates are not automatically function solutions. Check original logarithm arguments, potential zero divisors, and the requested angle interval.',e,p,
 dict(prompt=r'Solve $\log_{1/3}(x+2)\le-1$ and state the domain before reversing the inequality.',answer=r'The domain is x>-2, and the solution is x≥1.',steps=[r'The logarithm is decreasing, so its argument must satisfy x+2≥(1/3)^(-1)=3.',r'The resulting interval x≥1 already meets the original domain.']),
 ['reciprocal logarithms','positive exponential substitution','trigonometric factor branches','amplitude and triangle synthesis'],
 [(r'\log_a b=\frac{\log_c b}{\log_c a}','Change of base','expressing several logarithms with one shared base','a,b,c are positive and a,c are not one.'),(r'\sin(2\theta)=2\sin\theta\cos\theta','Sine double angle','factoring a multiple-angle equation or recovering a sine-cosine product','Valid for all real θ; division by a factor still needs a nonzero check.'),(r'\cos(2\theta)=\frac{1-\tan^2\theta}{1+\tan^2\theta}','Tangent-based double angle','computing a cosine double angle from a known tangent','tanθ must be defined.'),(r'\max_\theta(a\sin\theta+b\cos\theta)=\sqrt{a^2+b^2}','Trigonometric amplitude','optimizing a real sine-cosine linear combination','θ ranges over all real angles; a restricted interval may exclude the equality point.')], 'trigonometry',track=12)
